import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.logging.*;
import com.sun.net.httpserver.*;

public class UserProfileService {
    private static final Logger log = Logger.getLogger("UserProfileService");
    private static Connection dbConn;

    public static void main(String[] args) throws Exception {
        dbConn = DriverManager.getConnection(
            System.getenv("DB_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/profile", new ProfileHandler());
        server.createContext("/api/search", new SearchHandler());
        server.createContext("/health", new HealthHandler());
        server.start();
        log.info("Service started on port 8080");
    }

    static class ProfileHandler implements HttpHandler {
        public void handle(HttpExchange ex) throws IOException {
            if (!"GET".equals(ex.getRequestMethod())) {
                ex.sendResponseHeaders(405, 0); ex.close(); return;
            }
            String query = ex.getRequestURI().getQuery();
            String userId = extractParam(query, "id");
            if (userId == null || userId.isEmpty()) {
                sendResponse(ex, 400, "{\"error\":\"missing id\"}");
                return;
            }
            // Input validation: only allow alphanumeric and hyphens for UUID format
            if (!userId.matches("[a-zA-Z0-9\\-]+")) {
                sendResponse(ex, 400, "{\"error\":\"invalid id format\"}");
                return;
            }
            try {
                String sql = "SELECT id, display_name, email, department FROM users WHERE id = '" + userId + "'";
                Statement stmt = dbConn.createStatement();
                ResultSet rs = stmt.executeQuery(sql);
                StringBuilder json = new StringBuilder("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) json.append(",");
                    json.append(String.format(
                        "{\"id\":\"%s\",\"name\":\"%s\",\"email\":\"%s\",\"dept\":\"%s\"}",
                        rs.getString(1), rs.getString(2), rs.getString(3), rs.getString(4)
                    ));
                    first = false;
                }
                json.append("]");
                sendResponse(ex, 200, json.toString());
            } catch (SQLException e) {
                log.warning("DB error: " + e.getMessage());
                sendResponse(ex, 500, "{\"error\":\"internal\"}");
            }
        }
    }

    static class SearchHandler implements HttpHandler {
        public void handle(HttpExchange ex) throws IOException {
            if (!"GET".equals(ex.getRequestMethod())) {
                ex.sendResponseHeaders(405, 0); ex.close(); return;
            }
            String query = ex.getRequestURI().getQuery();
            String term = extractParam(query, "q");
            String dept = extractParam(query, "dept");
            if (term == null || term.length() < 2) {
                sendResponse(ex, 400, "{\"error\":\"search term too short\"}");
                return;
            }
            try {
                String sql = "SELECT id, display_name, department FROM users WHERE "
                    + "display_name LIKE '%" + term + "%'";
                if (dept != null && !dept.isEmpty()) {
                    sql += " AND department = '" + dept + "'";
                }
                sql += " LIMIT 20";
                Statement stmt = dbConn.createStatement();
                ResultSet rs = stmt.executeQuery(sql);
                StringBuilder json = new StringBuilder("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) json.append(",");
                    json.append(String.format(
                        "{\"id\":\"%s\",\"name\":\"%s\",\"dept\":\"%s\"}",
                        rs.getString(1), rs.getString(2), rs.getString(3)
                    ));
                    first = false;
                }
                json.append("]");
                sendResponse(ex, 200, json.toString());
            } catch (SQLException e) {
                log.warning("Search error: " + e.getMessage());
                sendResponse(ex, 500, "{\"error\":\"internal\"}");
            }
        }
    }

    static class HealthHandler implements HttpHandler {
        public void handle(HttpExchange ex) throws IOException {
            sendResponse(ex, 200, "{\"status\":\"ok\"}");
        }
    }

    static String extractParam(String query, String name) {
        if (query == null) return null;
        for (String param : query.split("&")) {
            String[] kv = param.split("=", 2);
            if (kv.length == 2 && kv[0].equals(name)) {
                try { return URLDecoder.decode(kv[1], "UTF-8"); }
                catch (Exception e) { return kv[1]; }
            }
        }
        return null;
    }

    static void sendResponse(HttpExchange ex, int code, String body) throws IOException {
        ex.getResponseHeaders().set("Content-Type", "application/json");
        byte[] b = body.getBytes("UTF-8");
        ex.sendResponseHeaders(code, b.length);
        ex.getResponseBody().write(b);
        ex.close();
    }
}
